-- Validate the source data before inserting into Django tables.
DO $$
BEGIN
    IF (SELECT count(*) FROM stg_learner) <> 1000
       OR (SELECT count(DISTINCT id_number) FROM stg_learner) <> 1000
       OR (SELECT count(*) FROM stg_application) <> 1000
       OR (SELECT count(*) FROM stg_enrollment) <> 1000
       OR (SELECT count(*) FROM stg_final_result) <> 1000
       OR (SELECT count(*) FROM stg_exam_score) <> 1000 THEN
        RAISE EXCEPTION 'Expected 1000 rows for learners, applications, enrollments, and scores.';
    END IF;
    IF EXISTS (
        SELECT 1 FROM stg_enrollment e
        LEFT JOIN stg_learner l USING (id_number)
        WHERE l.id_number IS NULL
    ) THEN RAISE EXCEPTION 'Enrollment refers to an unknown learner.'; END IF;
    IF EXISTS (
        SELECT 1 FROM stg_final_result r
        WHERE NOT EXISTS (
            SELECT 1 FROM stg_class c
            JOIN stg_enrollment e USING (class_code)
            WHERE c.name=r.class_name AND e.id_number=r.id_number
        )
    ) THEN RAISE EXCEPTION 'Final score learner is not enrolled in that class.'; END IF;
    IF EXISTS (
        SELECT 1 FROM stg_application a
        LEFT JOIN stg_period p ON p.name=a.period_name
        WHERE p.period_code IS NULL
    ) THEN RAISE EXCEPTION 'Application refers to an unknown exam period.'; END IF;
    IF EXISTS (
        SELECT 1 FROM stg_room_assignment a
        WHERE NOT EXISTS (
            SELECT 1 FROM stg_application p
            WHERE p.period_name=a.period_name AND p.id_number=a.id_number
        )
        OR NOT EXISTS (
            SELECT 1 FROM stg_room r
            WHERE r.period_code=a.period_code AND r.room_code=a.room_code
        )
    ) THEN RAISE EXCEPTION 'Room assignment refers to an unknown candidate or room.'; END IF;
END $$;

-- Courses and learners.
INSERT INTO home_course (name, pass_threshold)
SELECT s.name, s.pass_threshold
FROM stg_course s
WHERE NOT EXISTS (SELECT 1 FROM home_course c WHERE c.name=s.name);
CREATE TEMP TABLE map_course ON COMMIT DROP AS
SELECT s.course_code, min(c.id) AS course_id, count(c.id) AS matches
FROM stg_course s JOIN home_course c ON c.name=s.name
GROUP BY s.course_code;
DO $$ BEGIN
    IF (SELECT count(*) FROM map_course WHERE matches=1) <> (SELECT count(*) FROM stg_course)
        THEN RAISE EXCEPTION 'Course name is missing or ambiguous in home_course.'; END IF;
    IF EXISTS (
        SELECT 1 FROM stg_course s JOIN map_course m USING (course_code)
        JOIN home_course c ON c.id=m.course_id
        WHERE c.pass_threshold<>s.pass_threshold
    ) THEN RAISE EXCEPTION 'Existing course has a different pass threshold.'; END IF;
END $$;
INSERT INTO home_learner (full_name, date_of_birth, id_number, phone, email)
SELECT s.full_name, s.date_of_birth, s.id_number, s.phone, s.email
FROM stg_learner s
WHERE NOT EXISTS (SELECT 1 FROM home_learner l WHERE l.id_number=s.id_number);
CREATE TEMP TABLE map_learner ON COMMIT DROP AS
SELECT s.id_number, min(l.id) AS learner_id, count(l.id) AS matches
FROM stg_learner s JOIN home_learner l ON l.id_number=s.id_number
GROUP BY s.id_number;
DO $$ BEGIN
    IF (SELECT count(*) FROM map_learner WHERE matches=1) <> (SELECT count(*) FROM stg_learner)
        THEN RAISE EXCEPTION 'Learner ID mapping is missing or ambiguous.'; END IF;
    IF EXISTS (
        SELECT 1 FROM stg_learner s JOIN map_learner m USING (id_number)
        JOIN home_learner l ON l.id=m.learner_id
        WHERE l.full_name<>s.full_name
    ) THEN RAISE EXCEPTION 'An existing learner ID belongs to another name.'; END IF;
END $$;

-- Teachers and classes.
INSERT INTO home_teacher (full_name, phone, email, user_id)
SELECT s.full_name, s.phone, s.email, NULL
FROM stg_teacher s
WHERE NOT EXISTS (SELECT 1 FROM home_teacher t WHERE t.email=s.email);
CREATE TEMP TABLE map_teacher ON COMMIT DROP AS
SELECT s.teacher_code, min(t.id) AS teacher_id, count(t.id) AS matches
FROM stg_teacher s JOIN home_teacher t ON t.email=s.email
GROUP BY s.teacher_code;
DO $$ BEGIN
    IF (SELECT count(*) FROM map_teacher WHERE matches=1) <> (SELECT count(*) FROM stg_teacher)
        THEN RAISE EXCEPTION 'Teacher email mapping is missing or ambiguous.'; END IF;
    IF EXISTS (
        SELECT 1 FROM stg_teacher s JOIN map_teacher m USING (teacher_code)
        JOIN home_teacher t ON t.id=m.teacher_id
        WHERE t.full_name<>s.full_name
    ) THEN RAISE EXCEPTION 'An existing teacher email belongs to another name.'; END IF;
END $$;
INSERT INTO home_trainingclass
(name, course_id, learning_format, schedule, start_date, max_students, status, close_reason, final_results_locked_at, final_results_locked_by_id)
SELECT s.name, mc.course_id, s.learning_format, s.schedule, s.start_date,
       s.max_students, s.status, '', NULL, NULL
FROM stg_class s JOIN map_course mc USING (course_code)
WHERE NOT EXISTS (SELECT 1 FROM home_trainingclass c WHERE c.name=s.name);
CREATE TEMP TABLE map_class ON COMMIT DROP AS
SELECT s.class_code, min(c.id) AS class_id, count(c.id) AS matches,
       min(c.course_id) AS course_id
FROM stg_class s JOIN home_trainingclass c ON c.name=s.name
GROUP BY s.class_code;
DO $$ BEGIN
    IF (SELECT count(*) FROM map_class WHERE matches=1) <> (SELECT count(*) FROM stg_class)
        THEN RAISE EXCEPTION 'Class name mapping is missing or ambiguous.'; END IF;
    IF EXISTS (
        SELECT 1 FROM stg_class s JOIN map_class m USING (class_code)
        JOIN map_course mc USING (course_code)
        WHERE m.course_id<>mc.course_id
    ) THEN RAISE EXCEPTION 'An existing class is linked to a different course.'; END IF;
    IF EXISTS (
        SELECT 1 FROM stg_class s JOIN map_class m USING (class_code)
        JOIN home_trainingclass c ON c.id=m.class_id
        WHERE c.learning_format IS DISTINCT FROM s.learning_format
           OR c.schedule IS DISTINCT FROM s.schedule
           OR c.start_date IS DISTINCT FROM s.start_date
           OR c.max_students IS DISTINCT FROM s.max_students
    ) THEN RAISE EXCEPTION 'An existing class differs from the import file.'; END IF;
END $$;
INSERT INTO home_classassignment
(training_class_id, teacher_id, assigned_at, is_active, removed_at, removal_reason)
SELECT mc.class_id, mt.teacher_id, CURRENT_TIMESTAMP, TRUE, NULL, ''
FROM stg_class_assignment s
JOIN map_class mc USING (class_code)
JOIN map_teacher mt USING (teacher_code)
WHERE NOT EXISTS (
    SELECT 1 FROM home_classassignment a
    WHERE a.training_class_id=mc.class_id AND a.teacher_id=mt.teacher_id AND a.is_active=TRUE
);
INSERT INTO home_enrollment (training_class_id, learner_id, created_at)
SELECT mc.class_id, ml.learner_id, CURRENT_TIMESTAMP
FROM stg_enrollment s JOIN map_class mc USING (class_code)
JOIN map_learner ml USING (id_number)
WHERE NOT EXISTS (
    SELECT 1 FROM home_enrollment e
    WHERE e.training_class_id=mc.class_id AND e.learner_id=ml.learner_id
);
DO $$ BEGIN
    IF EXISTS (
        SELECT 1 FROM home_trainingclass c
        JOIN map_class m ON m.class_id=c.id
        WHERE (SELECT count(*) FROM home_enrollment e WHERE e.training_class_id=c.id)>c.max_students
    ) THEN RAISE EXCEPTION 'A class exceeds its maximum enrollment capacity.'; END IF;
END $$;

-- Exam periods, applications, rooms, and scores.
INSERT INTO home_examperiod
(name, cert_type_id, exam_date, registration_deadline, max_candidates, score_scale, status, created_at)
SELECT s.name, mc.course_id, s.exam_date, s.registration_deadline,
       s.max_candidates, s.score_scale, s.status, CURRENT_TIMESTAMP
FROM stg_period s JOIN map_course mc USING (course_code)
WHERE NOT EXISTS (SELECT 1 FROM home_examperiod p WHERE p.name=s.name);
CREATE TEMP TABLE map_period ON COMMIT DROP AS
SELECT s.period_code, min(p.id) AS period_id, count(p.id) AS matches,
       min(p.cert_type_id) AS course_id
FROM stg_period s JOIN home_examperiod p ON p.name=s.name
GROUP BY s.period_code;
DO $$ BEGIN
    IF (SELECT count(*) FROM map_period WHERE matches=1) <> (SELECT count(*) FROM stg_period)
        THEN RAISE EXCEPTION 'Exam period mapping is missing or ambiguous.'; END IF;
    IF EXISTS (
        SELECT 1 FROM stg_period s JOIN map_period mp USING (period_code)
        JOIN map_course mc USING (course_code)
        JOIN home_examperiod p ON p.id=mp.period_id
        WHERE mp.course_id<>mc.course_id OR p.exam_date<>s.exam_date
           OR p.registration_deadline<>s.registration_deadline
           OR p.max_candidates<>s.max_candidates OR p.score_scale<>s.score_scale
           OR p.status<>s.status
    ) THEN RAISE EXCEPTION 'An existing exam period differs from the import file.'; END IF;
END $$;
INSERT INTO home_examapplication
(exam_period_id, full_name, date_of_birth, phone, id_number, email, source, registered_at, status)
SELECT mp.period_id, s.full_name, s.date_of_birth, s.phone, s.id_number,
       s.email, 'google_form', CURRENT_TIMESTAMP, 'valid'
FROM stg_application s
JOIN stg_period sp ON sp.name=s.period_name
JOIN map_period mp USING (period_code)
WHERE NOT EXISTS (
    SELECT 1 FROM home_examapplication a
    WHERE a.exam_period_id=mp.period_id AND a.id_number=s.id_number
);
CREATE TEMP TABLE map_application ON COMMIT DROP AS
SELECT mp.period_code, s.id_number, min(a.id) AS application_id, count(a.id) AS matches
FROM stg_application s
JOIN stg_period sp ON sp.name=s.period_name
JOIN map_period mp USING (period_code)
JOIN home_examapplication a ON a.exam_period_id=mp.period_id AND a.id_number=s.id_number
GROUP BY mp.period_code, s.id_number;
DO $$ BEGIN
    IF (SELECT count(*) FROM map_application WHERE matches=1) <> (SELECT count(*) FROM stg_application)
        THEN RAISE EXCEPTION 'Application mapping is missing or duplicated within an exam period.'; END IF;
    IF EXISTS (
        SELECT 1 FROM stg_application s JOIN stg_period sp ON sp.name=s.period_name
        JOIN map_period mp USING (period_code)
        JOIN map_application ma ON ma.period_code=mp.period_code AND ma.id_number=s.id_number
        JOIN home_examapplication a ON a.id=ma.application_id
        WHERE a.full_name<>s.full_name OR a.email<>s.email
           OR a.phone<>s.phone OR a.date_of_birth<>s.date_of_birth
           OR a.status<>'valid'
    ) THEN RAISE EXCEPTION 'Existing application name/email differs from the import file.'; END IF;
END $$;
INSERT INTO home_examroom (exam_period_id, name, session, capacity)
SELECT mp.period_id, s.name, s.session, s.capacity
FROM stg_room s JOIN map_period mp USING (period_code)
WHERE NOT EXISTS (
    SELECT 1 FROM home_examroom r
    WHERE r.exam_period_id=mp.period_id AND r.name=s.name
);
CREATE TEMP TABLE map_room ON COMMIT DROP AS
SELECT s.period_code, s.room_code, min(r.id) AS room_id, count(r.id) AS matches
FROM stg_room s JOIN map_period mp USING (period_code)
JOIN home_examroom r ON r.exam_period_id=mp.period_id AND r.name=s.name
GROUP BY s.period_code, s.room_code;
DO $$ BEGIN
    IF (SELECT count(*) FROM map_room WHERE matches=1) <> (SELECT count(*) FROM stg_room)
        THEN RAISE EXCEPTION 'Exam room mapping is missing or ambiguous.'; END IF;
    IF EXISTS (
        SELECT 1 FROM stg_room s JOIN map_room mr USING (period_code, room_code)
        JOIN home_examroom r ON r.id=mr.room_id
        WHERE r.session<>s.session OR r.capacity<>s.capacity
    ) THEN RAISE EXCEPTION 'An existing room has a different session or capacity.'; END IF;
END $$;
INSERT INTO home_examroomassignment (exam_room_id, application_id, assigned_at)
SELECT mr.room_id, ma.application_id, CURRENT_TIMESTAMP
FROM stg_room_assignment s
JOIN map_room mr USING (period_code, room_code)
JOIN map_application ma ON ma.period_code=s.period_code AND ma.id_number=s.id_number
WHERE NOT EXISTS (
    SELECT 1 FROM home_examroomassignment a
    WHERE a.exam_room_id=mr.room_id AND a.application_id=ma.application_id
);
CREATE TEMP TABLE map_room_assignment ON COMMIT DROP AS
SELECT s.period_code, s.room_code, s.id_number, min(a.id) AS assignment_id,
       count(a.id) AS matches
FROM stg_room_assignment s
JOIN map_room mr USING (period_code, room_code)
JOIN map_application ma ON ma.period_code=s.period_code AND ma.id_number=s.id_number
JOIN home_examroomassignment a ON a.exam_room_id=mr.room_id AND a.application_id=ma.application_id
GROUP BY s.period_code, s.room_code, s.id_number;
DO $$ BEGIN
    IF (SELECT count(*) FROM map_room_assignment WHERE matches=1) <> (SELECT count(*) FROM stg_room_assignment)
        THEN RAISE EXCEPTION 'Room assignment mapping is missing or ambiguous.'; END IF;
    IF EXISTS (
        SELECT 1 FROM map_room mr JOIN home_examroom r ON r.id=mr.room_id
        WHERE (SELECT count(*) FROM home_examroomassignment a WHERE a.exam_room_id=r.id)>r.capacity
    ) THEN RAISE EXCEPTION 'An exam room exceeds its capacity.'; END IF;
    IF EXISTS (
        SELECT 1 FROM map_room_assignment mra
        JOIN home_examroomassignment ra ON ra.id=mra.assignment_id
        JOIN home_examapplication app ON app.id=ra.application_id
        WHERE app.status<>'valid'
    ) THEN RAISE EXCEPTION 'Only valid applications can be assigned to an exam room.'; END IF;
    IF EXISTS (
        SELECT a.application_id
        FROM home_examroomassignment a
        JOIN home_examroom r ON r.id=a.exam_room_id
        JOIN map_period mp ON mp.period_id=r.exam_period_id
        GROUP BY mp.period_code, a.application_id
        HAVING count(*)>1
    ) THEN RAISE EXCEPTION 'A candidate is assigned to multiple rooms in the same exam period.'; END IF;
END $$;
INSERT INTO home_examscore
(assignment_id, score, is_absent, is_published, is_locked, entered_at, published_at)
SELECT mra.assignment_id, s.score, FALSE, FALSE, FALSE, CURRENT_TIMESTAMP, NULL
FROM stg_exam_score s
JOIN stg_period sp ON sp.name=s.period_name
JOIN map_period mp USING (period_code)
JOIN stg_room sr ON sr.period_code=mp.period_code AND sr.name=s.room_name AND sr.session=s.session
JOIN map_room_assignment mra
  ON mra.period_code=mp.period_code AND mra.room_code=sr.room_code AND mra.id_number=s.id_number
WHERE NOT EXISTS (SELECT 1 FROM home_examscore es WHERE es.assignment_id=mra.assignment_id);
DO $$ BEGIN
    IF (SELECT count(*) FROM home_examscore es
        JOIN map_room_assignment mra ON mra.assignment_id=es.assignment_id)
       <> (SELECT count(*) FROM stg_exam_score)
        THEN RAISE EXCEPTION 'Some exam scores are missing after import.'; END IF;
    IF EXISTS (
        SELECT 1 FROM stg_exam_score s
        JOIN stg_period sp ON sp.name=s.period_name
        JOIN map_period mp USING (period_code)
        JOIN stg_room sr ON sr.period_code=mp.period_code AND sr.name=s.room_name AND sr.session=s.session
        JOIN map_room_assignment mra
          ON mra.period_code=mp.period_code AND mra.room_code=sr.room_code AND mra.id_number=s.id_number
        JOIN home_examscore es ON es.assignment_id=mra.assignment_id
        WHERE es.score<>s.score
    ) THEN RAISE EXCEPTION 'An existing exam score differs from the import file.'; END IF;
END $$;

-- Final course scores.
INSERT INTO home_finalcourseresult
(training_class_id, learner_id, score, is_absent, is_published, published_at, modified_by_id, created_at, updated_at)
SELECT mc.class_id, ml.learner_id, s.score, FALSE, FALSE, NULL, NULL,
       CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
FROM stg_final_result s
JOIN stg_class sc ON sc.name=s.class_name
JOIN map_class mc USING (class_code)
JOIN map_learner ml USING (id_number)
WHERE NOT EXISTS (
    SELECT 1 FROM home_finalcourseresult fr
    WHERE fr.training_class_id=mc.class_id AND fr.learner_id=ml.learner_id
);
DO $$ BEGIN
    IF (SELECT count(*) FROM stg_final_result s
        JOIN stg_class sc ON sc.name=s.class_name
        JOIN map_class mc USING (class_code)
        JOIN map_learner ml USING (id_number)
        JOIN home_finalcourseresult fr
          ON fr.training_class_id=mc.class_id AND fr.learner_id=ml.learner_id)
       <> (SELECT count(*) FROM stg_final_result)
        THEN RAISE EXCEPTION 'Some final scores are missing after import.'; END IF;
    IF EXISTS (
        SELECT 1 FROM stg_final_result s
        JOIN stg_class sc ON sc.name=s.class_name
        JOIN map_class mc USING (class_code)
        JOIN map_learner ml USING (id_number)
        JOIN home_finalcourseresult fr
          ON fr.training_class_id=mc.class_id AND fr.learner_id=ml.learner_id
        WHERE fr.score<>s.score
    ) THEN RAISE EXCEPTION 'An existing final score differs from the import file.'; END IF;
END $$;

-- Counts of the imported data; transaction commits only if all checks pass.
SELECT 'learners' AS imported_table, count(*) AS rows FROM map_learner
UNION ALL SELECT 'classes', count(*) FROM map_class
UNION ALL SELECT 'enrollments', count(*) FROM home_enrollment e
  JOIN map_class c ON c.class_id=e.training_class_id
  JOIN map_learner l ON l.learner_id=e.learner_id
UNION ALL SELECT 'applications', count(*) FROM map_application
UNION ALL SELECT 'exam rooms', count(*) FROM map_room
UNION ALL SELECT 'exam scores', count(*) FROM home_examscore es
  JOIN map_room_assignment a ON a.assignment_id=es.assignment_id
UNION ALL SELECT 'final scores', count(*) FROM home_finalcourseresult fr
  JOIN map_class c ON c.class_id=fr.training_class_id
  JOIN map_learner l ON l.learner_id=fr.learner_id;
COMMIT;
